import React, { useState, useEffect } from "react";
import "./Dashboard.css";

function Dashboard({ userData, setUserData }) {
  const [showProfile, setShowProfile] = useState(false);
  const [editableData, setEditableData] = useState(userData);

  useEffect(() => {
    setEditableData(userData);
  }, [userData]);

  // ✅ SAVE PROFILE CHANGES
  const saveProfile = () => {
    localStorage.setItem("userData", JSON.stringify(editableData));
    setUserData(editableData);
    setShowProfile(false);
  };

  return (
    <div className="dashboard-main">
      <div className="container">

        {/* NAVBAR */}
        <div className="navbar">
          <div className="logo">FinSight</div>

          {/* PROFILE ICON */}
          <div
            style={{ cursor: "pointer", fontSize: "22px" }}
            onClick={() => setShowProfile(true)}
          >
            👤
          </div>
        </div>

        {/* PROFILE PANEL */}
        {showProfile && (
          <div style={{
            position: "fixed",
            top: 0,
            right: 0,
            width: "320px",
            height: "100%",
            background: "white",
            boxShadow: "-5px 0 20px rgba(0,0,0,0.1)",
            padding: "20px",
            zIndex: 1000
          }}>
            <h2>Profile</h2>

            <label>Email</label>
            <input
              value={editableData.email || ""}
              onChange={(e) =>
                setEditableData({ ...editableData, email: e.target.value })
              }
            />

            <label>Income Type</label>
            <input
              value={editableData.income || ""}
              onChange={(e) =>
                setEditableData({ ...editableData, income: e.target.value })
              }
            />

            <label>Categories</label>
            <input
              value={(editableData.categories || []).join(", ")}
              onChange={(e) =>
                setEditableData({
                  ...editableData,
                  categories: e.target.value.split(",")
                })
              }
            />

            <label>Budget Limits</label>
            <textarea
              value={JSON.stringify(editableData.limits || {}, null, 2)}
              onChange={(e) =>
                setEditableData({
                  ...editableData,
                  limits: JSON.parse(e.target.value || "{}")
                })
              }
            />

            <button onClick={saveProfile}>Save</button>

            <button
              onClick={() => setShowProfile(false)}
              style={{ marginTop: "10px" }}
            >
              Close
            </button>
          </div>
        )}

        {/* MAIN DASHBOARD CONTENT */}
        <div className="hero">
          <h1>Welcome, {userData.email || "User"}</h1>
          <p>Your financial overview</p>
        </div>

      </div>
    </div>
  );
}

export default Dashboard;
